/* [SOLO TRIPWIRE] — Παγίδα Supabase για την έκδοση Solo (Φάση 1).
 * Καμία κλήση δικτύου. Καταγράφει τις 2 δηλωμένες κλήσεις εκκίνησης
 * (supabase.createClient, auth.onAuthStateChange) στο __tripwire.declared
 * και κάθε άλλη χρήση στο __tripwire.uses. */
(function (global) {
    'use strict';

    const tripwire = {
        signature: '[SOLO TRIPWIRE]',
        declared: [],
        uses: []
    };
    global.__tripwire = tripwire;

    function createTrapProxy(prefix) {
        const fn = function () {
            tripwire.uses.push(prefix);
            console.warn('[SOLO TRIPWIRE] Blocked call:', prefix);
            return createTrapProxy(prefix + '()');
        };
        return new Proxy(fn, {
            get(target, prop) {
                if (prop === 'then') {
                    // Make awaited calls resolve safely with disabled error
                    return function (resolve) {
                        return resolve({ data: null, error: { message: 'Solo mode: Supabase disabled', code: 'SOLO_TRIPWIRE' } });
                    };
                }
                if (prop === 'unsubscribe') {
                    return function () {};
                }
                if (typeof prop === 'symbol') return target[prop];
                const nextPath = prefix ? `${prefix}.${String(prop)}` : String(prop);
                if (nextPath === 'auth.onAuthStateChange') {
                    return function () {
                        tripwire.declared.push('auth.onAuthStateChange');
                        // ΔΕΝ καλεί το callback (01-phase1-design.md §2.1 B2)
                        return { data: { subscription: { unsubscribe: function () {} } } };
                    };
                }
                return createTrapProxy(nextPath);
            }
        });
    }

    global.supabase = {
        createClient: function () {
            tripwire.declared.push('supabase.createClient');
            return createTrapProxy('');
        }
    };
})(typeof window !== 'undefined' ? window : globalThis);
